INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(49211, 'Numbers 13:28', 'Numbers', 13, 28, 'خو د هغه ځای خلک قوي او ښارونه یې ډېر لوی او دېوال لرونکي دي. برسېره پردې، مونږ هلته د عناقیانو اولاده هم ولیدله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers13_verse_28.mp3', '', 1761754199, 1761754199),
(49212, 'Numbers 13:29', 'Numbers', 13, 29, 'عمالیقیان په جنوبي دښته کې اوسیږي، حیتیان، یبوسیان او اموریان په غرنۍ سیمه کې دي او کنعانیان د مدیترانې د بحیرې او د اردن د سیند په غاړه اوسیږي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers13_verse_29.mp3', '', 1761754199, 1761754199),
(49213, 'Numbers 13:30', 'Numbers', 13, 30, 'کالیب هغه خلک غلي کړل چې د موسی په ضد یې شکایتونه کول او ویې ویل: «راځئ چې اوس لاړ شو او دا ځمکه ونیسو. زه پوهېږم چې مونږ دا کار کولای شو!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers13_verse_30.mp3', '', 1761754199, 1761754199),
(49214, 'Numbers 13:31', 'Numbers', 13, 31, 'خو هغو کسانو چې د کالیب سره تللي وو، وویل: «نه، مونږ دومره قوي نه یو چې په هغوی باندې حمله وکړو، د هغه ځای خلک زمونږ څخه ډېر قوي دي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers13_verse_31.mp3', '', 1761754199, 1761754199),
(49215, 'Numbers 13:32', 'Numbers', 13, 32, 'نو هغوی د هغې ځمکې په اړه چې کتلې یې وه د اسراییلیانو په منځ کې بد خبر خپور کړ. هغوی وویل: «هغه ځمکه دومره حاصل هم نه ورکوي چې د هغه ځای د خلکو د مړولو دپاره کفایت وکړي. هرڅوک چې مونږ لیده ډېر لوړ قد یې درلود،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers13_verse_32.mp3', '', 1761754199, 1761754199),
(49216, 'Numbers 13:33', 'Numbers', 13, 33, 'حتی مونږ په هغه ځای کې د عناقیانو اولاده هم ولیدله. هغوی دومره قوي وو او لوړ قدونه یې درلودل چې مونږ ته خپل ځانونه داسې کوچني ښکاره شول لکه د ملخانو په شان او هغوی ته هم همداسې ښکاره کېدلو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/numbers13_verse_33.mp3', '', 1761754199, 1761754199),
(49217, 'Leviticus 27:1', 'Leviticus', 27, 1, 'څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus27_verse_1.mp3', '', 1761754199, 1761754199),
(49218, 'Leviticus 27:2', 'Leviticus', 27, 2, '«د اسراییلیانو سره خبرې وکړه او ورته ووایه چې که چېرې څوک یو بل کس د ځانګړي نذر په توګه څښتن ته وقف کړي، نو هغه کس به د لاندېنیو پیسو په ورکولو سره ازاد شي:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus27_verse_2.mp3', '', 1761754199, 1761754199),
(49219, 'Leviticus 27:8', 'Leviticus', 27, 8, 'که چېرې یو کس چې نذر ورکوي ډېر غریب وي او نه شي کولای چې دا ټاکل شوې اندازه ورکړي، هغه دې دا کس کاهن ته وړاندې کړي او کاهن به نذر ورکوونکي ته د هغه د توان سره سمه بیه وټاکي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus27_verse_8.mp3', '', 1761754199, 1761754199),
(49220, 'Leviticus 27:9', 'Leviticus', 27, 9, 'که چېرې د هغه نذر یو داسې حیوان وي چې څښتن ته د نذرانې په توګه د منلو وړ وي، نو داسې سوغات چې څښتن ته ورکول کیږي، هغه سپېڅلی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus27_verse_9.mp3', '', 1761754199, 1761754199),
(49221, 'Leviticus 27:10', 'Leviticus', 27, 10, 'که هغه حیوان ښه وي یا خراب، هغه نه شي کولای چې د بل حیوان سره یې بدل کړي. که چېرې داسې وکړي، نو دواړه حیوانات د څښتن کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus27_verse_10.mp3', '', 1761754199, 1761754199),
(49222, 'Leviticus 27:11', 'Leviticus', 27, 11, 'که چېرې د هغه نذر یو ناپاک حیوان وي، دا چې هغه څښتن ته د نذرانې په توګه د منلو وړ نه دی، نو هغه حیوان باید کاهن ته راوستل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus27_verse_11.mp3', '', 1761754199, 1761754199),
(49223, 'Leviticus 27:12', 'Leviticus', 27, 12, 'کاهن دې د هغه د ښه والي یا بدوالي له مخې بیه وټاکي او دا به اخرنۍ بیه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus27_verse_12.mp3', '', 1761754199, 1761754199),
(49224, 'Leviticus 27:13', 'Leviticus', 27, 13, 'که چېرې خاوند یې وغواړي چې هغه حیوان بېرته واخلي، باید د هغې د بیې څخه شل فیصده زیات ورکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus27_verse_13.mp3', '', 1761754199, 1761754199),
(49225, 'Leviticus 27:14', 'Leviticus', 27, 14, 'که چېرې یو کس خپل کور څښتن ته وقف کوي، کاهن به ورته د هغه د ښه والي یا بدوالي له مخې بیه وټاکي او هغه به اخرنۍ بیه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus27_verse_14.mp3', '', 1761754199, 1761754199),
(49226, 'Leviticus 27:15', 'Leviticus', 27, 15, 'که چېرې هغه کس چې خپل کور یې وقف کړی دی، وغواړي چې هغه بېرته واخلي، باید شل فیصده اضافه بیه ادا کړي او کور به بیا د هغه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus27_verse_15.mp3', '', 1761754199, 1761754199),
(49227, 'Leviticus 27:16', 'Leviticus', 27, 16, 'که چېرې یو کس څښتن ته د خپلې کورنۍ د ځمکې کومه برخه وقف کوي، د هغې بیه دې د هغه تخم د اندازې له مخې وټاکل شي چې په هغه ځمکه کې کرل کیږي، یعنې د دوه سوه کیلو ګرامو اوربشو تخم دپاره پنځوس د سپینو زرو سکې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus27_verse_16.mp3', '', 1761754199, 1761754199),
(49228, 'Leviticus 27:17', 'Leviticus', 27, 17, 'که چېرې هغه دا ځمکه د بېرته ورکولو د کال څخه وروسته سمدلاسه وقف کړي، نو ټوله بیه دې ادا کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus27_verse_17.mp3', '', 1761754199, 1761754199),
(49229, 'Leviticus 27:18', 'Leviticus', 27, 18, 'خو که چېرې هغه کس خپله ځمکه له دې څخه وروسته وقف کړي، کاهن به د هغې بیه د هغو کلونو د شمېر له مخې حساب کړي چې د بېرته ورکولو تر راتلونکي کال پورې پاتې وي او کمه بیه به وټاکي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus27_verse_18.mp3', '', 1761754199, 1761754199),
(49230, 'Leviticus 27:19', 'Leviticus', 27, 19, 'که چېرې هغه کس چې ځمکه یې وقف کړې ده وغواړي چې هغه بېرته واخلي، باید د اضافه شلو فیصدو سره بیه ادا کړي او ځمکه به بېرته د هغه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus27_verse_19.mp3', '', 1761754199, 1761754199),
(49231, 'Leviticus 27:20', 'Leviticus', 27, 20, 'که چېرې هغه ځمکه په بل چا باندې خرڅوي، نو هغه دې لومړی بېرته په بیه واخلي، پرته له دې د بېرته اخیستلو حق د تل دپاره له لاسه ورکوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus27_verse_20.mp3', '', 1761754199, 1761754199),
(49232, 'Leviticus 27:21', 'Leviticus', 27, 21, 'د بېرته ورکولو په راتلونکي کال کې به دا ځمکه سپېڅلې او د څښتن تلپاتې ملکیت شي. هغه به د کاهنانو شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus27_verse_21.mp3', '', 1761754199, 1761754199),
(49233, 'Leviticus 27:22', 'Leviticus', 27, 22, 'که چېرې یو کس څښتن ته داسې یو پټی وقف کړي چې اخیستی یې وي او د هغه د کورنۍ د ځمکې برخه نه وي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus27_verse_22.mp3', '', 1761754199, 1761754199),
(49234, 'Leviticus 27:23', 'Leviticus', 27, 23, 'کاهن به د هغه بیه د هغو کلونو د شمېر له مخې حساب کړي چې د بېرته ورکولو تر راتلونکي کال پورې پاتې وي او هغه کس باید په هماغه ورځ بیه ادا کړي. پیسې د څښتن کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus27_verse_23.mp3', '', 1761754199, 1761754199),
(49235, 'Leviticus 27:24', 'Leviticus', 27, 24, 'دا پټی به د بېرته ورکولو په کال کې د هغه اصلي خاوند یا د هغه اولادې ته بېرته ورکړای شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus27_verse_24.mp3', '', 1761754199, 1761754199),
(49236, 'Leviticus 27:25', 'Leviticus', 27, 25, 'ټولې بیې باید د سپېڅلي ځای د اندازې له مخې وټاکل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus27_verse_25.mp3', '', 1761754199, 1761754199),
(49237, 'Leviticus 27:26', 'Leviticus', 27, 26, 'لومړنی زېږېدلی حیوان له پخوا څخه د څښتن دی، نو هېڅوک نه شي کولای چې هغه څښتن ته وقف کړي. که هغه یو خوسی وي، یو وری یا سېرلی وي، که هغه نر وي یا ښځه، هغه د څښتن دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus27_verse_26.mp3', '', 1761754199, 1761754199),
(49238, 'Leviticus 27:27', 'Leviticus', 27, 27, 'که چېرې هغه یو ناپاک حیوان وي، کېدای شي چې په اصلي بیه د اضافه شلو فیصدو سره بېرته واخیستل شي. که چېرې هغه بېرته وانخیستل شي، کېدای شي چې په بل چا باندې په اصلي بیه خرڅ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus27_verse_27.mp3', '', 1761754199, 1761754199),
(49239, 'Leviticus 27:28', 'Leviticus', 27, 28, 'هېڅوک نه شي کولای چې داسې څه خرڅ کړي یا یې بېرته واخلي چې پرته له کوم شرط څخه یې څښتن ته وقف کړی وي، که هغه یو انسان وي، یو حیوان، یا د کورنۍ ځمکه وي. هغه په تلپاتې توګه د څښتن دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus27_verse_28.mp3', '', 1761754199, 1761754199),
(49240, 'Leviticus 27:29', 'Leviticus', 27, 29, 'څوک چې په مرګ محکوم شوی وي، هغه نه شي کولای چې خپل ژوند بېرته په بیه واخلي، هغه باید ووژل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus27_verse_29.mp3', '', 1761754199, 1761754199),
(49241, 'Leviticus 27:30', 'Leviticus', 27, 30, 'د ځمکې د ټولو حاصلاتو لسمه برخه که هغه غلې دانې وي یا مېوه، هغه د څښتن ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus27_verse_30.mp3', '', 1761754199, 1761754199),
(49242, 'Leviticus 27:31', 'Leviticus', 27, 31, 'که چېرې یو کس وغواړي چې د هغې څخه لږ بېرته واخلي، هغه باید د اضافه شلو فیصدو سره اصلي بیه ادا کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus27_verse_31.mp3', '', 1761754199, 1761754199),
(49243, 'Leviticus 27:32', 'Leviticus', 27, 32, 'کله چې څوک خپلې پادې او رمې شمېري، د هغو څخه هر لسم حیوان د څښتن دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus27_verse_32.mp3', '', 1761754199, 1761754199),
(49244, 'Leviticus 27:33', 'Leviticus', 27, 33, 'هغه کس نه شي کولای چې خپل حیوانات داسې ترتیب کړي چې خراب حیوانات ورڅخه غوره کړي او نه شي کولای چې هغه بدل کړي. که چېرې هغه یو حیوان د بل سره بدل کړي، بیا دواړه حیوانات د څښتن کیږي او بېرته په بیه نه شي اخیستل کېدای.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus27_verse_33.mp3', '', 1761754199, 1761754199),
(49245, 'Leviticus 27:34', 'Leviticus', 27, 34, 'دا هغه امرونه دي چې څښتن موسی ته د سینا په غره باندې د اسراییلیانو دپاره ورکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus27_verse_34.mp3', '', 1761754199, 1761754199),
(49246, 'Ezekiel 36:1', 'Ezekiel', 36, 1, 'څښتن وویل: «نو ته، ای فاني انسانه، د اسراییلو غرونو ته نبوت وکړه او ورته ووایه چې هغه پیغام ته غوږ ونیسي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel36_verse_1.mp3', '', 1761754199, 1761754199),
(49247, 'Ezekiel 36:2', 'Ezekiel', 36, 2, 'چې زه څښتن تعالی یې هغوی ته ورکوم: ‹د اسراییلو دښمنانو خوشحالي کوله او ویل یې چې هغه پخواني د اسراییلو لوړ ځایونه اوس زمونږ دي!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel36_verse_2.mp3', '', 1761754199, 1761754199),
(49248, 'Ezekiel 36:3', 'Ezekiel', 36, 3, 'نو نبوت وکړه او څه چې زه څښتن تعالی وایم هغه اعلان کړه. کله چې شاوخوا قومونو د اسراییلو غرونه ونیول او هغه یې وران او تر پښو لاندې کړل، نو هغوی ټولو په اسراییلو باندې ملنډې ووهلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel36_verse_3.mp3', '', 1761754199, 1761754199),
(49249, 'Ezekiel 36:4', 'Ezekiel', 36, 4, 'نو ای د اسراییلو غرونو، هغه څه چې زه څښتن تعالی یې تاسو ته وایم، واورئ. هو، غرونو، غونډیو، تنګیو، درو، وران شویو ځایونو او هغو ویجاړ شویو ښارونو ته وایم چې تاسو د شاوخوا قومونو ته د تالا کولو او سپکاوي موقعه برابره کړه.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel36_verse_4.mp3', '', 1761754199, 1761754199),
(49250, 'Ezekiel 36:5', 'Ezekiel', 36, 5, 'نو په دې خاطر څښتن تعالی داسې وایي: ‹ما د خپل سخت قهر په وخت کې د شاوخوا قومونو او په ځانګړې توګه د ادوم په ضد خبرې کړې دي. هغوی په خوشحالۍ او کینې زما وطن او د هغه څړځایونه د غنیمت په توګه ونیول.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel36_verse_5.mp3', '', 1761754199, 1761754199),
(49251, 'Ezekiel 36:6', 'Ezekiel', 36, 6, 'د اسراییلو د هېواد په هکله نبوت وکړه او غرونو، غونډیو، تنګیو او درو ته ووایه چې زه څښتن تعالی داسې وایم: ‹ګورئ، زه د سخت قهر په حالت کې خبرې کوم، ځکه چې تاسو د نورو قومونو سپکاوی زغملی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel36_verse_6.mp3', '', 1761754199, 1761754199),
(49252, 'Ezekiel 36:7', 'Ezekiel', 36, 7, 'نو زه څښتن تعالی قسم خورم چې شاوخوا قومونه به په خپله سپک شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel36_verse_7.mp3', '', 1761754199, 1761754199),
(49253, 'Ezekiel 36:8', 'Ezekiel', 36, 8, 'خو ای د اسراییلو غرونو، ستاسو ونې به يوځل بیا پاڼې وکړي او زما د خلکو یعنې اسراییلو دپاره به مېوه ونیسي. هغوی به ډېر زر خپل وطن ته بېرته راستانه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel36_verse_8.mp3', '', 1761754199, 1761754199),
(49254, 'Ezekiel 36:9', 'Ezekiel', 36, 9, 'ګورئ، زه ستاسو په خوا یم او تاسو ته ډاډ درکوم چې ستاسو ځمکه به بیا قلبه شي او تخمونه به په کې وکرل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel36_verse_9.mp3', '', 1761754199, 1761754199),
(49255, 'Ezekiel 36:10', 'Ezekiel', 36, 10, 'زه به ستاسو یعنې د اسراییلو د ټول قوم نفوس زیات کړم. خلک به ستاسو په ښارونو کې واوسیږي او هغه څه چې په کنډوالو بدل شوي دي، هغه به بیا ودان شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel36_verse_10.mp3', '', 1761754199, 1761754199),
(49256, 'Ezekiel 36:11', 'Ezekiel', 36, 11, 'زه به ستاسو د انسانانو او څارويو شمېر ډېر کړم. هغوی به د مخکې نه زیات شي او د هغوی نسل به هم زیات شي. زه به هغوی پرېږدم چې په هغه ځای کې چې مخکې اوسېدل، هم هلته واوسېږي او د مخکې نه به یې زیات سوکاله کړم. بیا به تاسو پوه شئ چې زه څښتن یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel36_verse_11.mp3', '', 1761754199, 1761754199),
(49257, 'Ezekiel 36:12', 'Ezekiel', 36, 12, 'زه به خپل خلک اسراییل پرېږدم چې په خپل وطن کې واوسیږي. دا به د اسراییلو خپل وطن شي او نور به تاسو پرېنږدئ چې د هغوی اولادونه له لوږې مړه شي.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel36_verse_12.mp3', '', 1761754199, 1761754199),
(49258, 'Ezekiel 36:13', 'Ezekiel', 36, 13, 'زه څښتن تعالی داسې وایم: ‹نور قومونه تاسو ته پېغور درکوي او وایي چې تاسو د اسراییلو وطن تباه کوئ او خپل قوم بې‌اولاده کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel36_verse_13.mp3', '', 1761754199, 1761754199),
(49259, 'Ezekiel 36:14', 'Ezekiel', 36, 14, 'خو نور به تاسو خلک نه تباه کوئ او خپل قوم به نه بې‌اولاده کوئ. ما څښتن تعالی داسې ویلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel36_verse_14.mp3', '', 1761754199, 1761754199),
(49260, 'Ezekiel 36:15', 'Ezekiel', 36, 15, 'زه به تاسو نور پرېنږدم چې د نورو قومونو سپکاوی واورئ او نه به هغوی په تاسو باندې ملنډې وهي. دا وطن به نور خپل قوم نه بې‌اولاده کوي. ما څښتن تعالی داسې ویلي دي.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel36_verse_15.mp3', '', 1761754199, 1761754199),
(49261, 'Ezekiel 36:16', 'Ezekiel', 36, 16, 'څښتن ماته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel36_verse_16.mp3', '', 1761754199, 1761754199),
(49262, 'Ezekiel 36:17', 'Ezekiel', 36, 17, '«ای فاني انسانه، کله چې اسراییلیان په خپل وطن کې اوسېدل، نو هغوی چې په کوم ډول خپل ژوند تېراوه، په خپلو عملونو باندې یې هغه وطن ناپاک کړ. زما په نظر د هغوی کړه وړه داسې ناپاک وو لکه ښځه چې د میاشتیني عادت په وخت کې ناپاکه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel36_verse_17.mp3', '', 1761754199, 1761754199),
(49263, 'Ezekiel 36:18', 'Ezekiel', 36, 18, 'په دې خاطر چې هغوی په دې وطن کې وینه تویه کړې وه او بتانو ته په عبادت کولو سره یې هغه وطن ناپاکه کړی ؤ، نو ما په هغوی باندې خپل قهر نازل کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel36_verse_18.mp3', '', 1761754199, 1761754199),
(49264, 'Ezekiel 36:19', 'Ezekiel', 36, 19, 'ما هغوی د هغوی د چلند او عملونو په سبب محاکمه او هغوی ته مې سزا ورکړه او هغوی مې په پردیو وطنونو کې خواره واره کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel36_verse_19.mp3', '', 1761754199, 1761754199),
(49265, 'Ezekiel 36:20', 'Ezekiel', 36, 20, 'هغوی چې هر‌چېرته تلل نو زما سپېڅلی نوم یې سپکاوه، ځکه چې خلکو به ویل چې دا د څښتن قوم دی، خو هغوی مجبور شول چې د هغه د وطن نه لاړ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel36_verse_20.mp3', '', 1761754199, 1761754199),
(49266, 'Ezekiel 36:21', 'Ezekiel', 36, 21, 'نو زه د خپل سپېڅلي نوم په خاطر اندېښمن شوم، ځکه اسراییلیان چې هر‌چېرته تلل، نو زما سپکاوی به یې کاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel36_verse_21.mp3', '', 1761754199, 1761754199),
(49267, 'Ezekiel 36:22', 'Ezekiel', 36, 22, 'نو اوس اسراییلیانو ته دا پیغام چې زه څښتن تعالی یې د هغوی دپاره لرم، ورسوه: ‹زه چې کوم کار کوم هغه ستاسو په خاطر نه، بلکې د خپل سپېڅلي نوم په خاطر یې کوم چې تاسو هغه په هر وطن کې چې ورته تللي یئ، هغه مو سپک کړی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel36_verse_22.mp3', '', 1761754199, 1761754199),
(49268, 'Ezekiel 36:23', 'Ezekiel', 36, 23, 'کله چې زه د خپل لوی نوم سپېڅلتوب نورو قومونو ته وښایم، کوم چې تاسو په هغوی کې سپک کړی دی، نو بیا به هغوی پوه شي چې زه څښتن یم. ما څښتن تعالی داسې ویلي دي. هغه وخت به زه ستاسو په وسیله قومونو ته دا وښایم چې زه سپېڅلی یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel36_verse_23.mp3', '', 1761754199, 1761754199),
(49269, 'Ezekiel 36:24', 'Ezekiel', 36, 24, 'زه به تاسو د ټولو قومونو او وطنونو نه راټول کړم او بېرته به مو خپل وطن ته راولم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel36_verse_24.mp3', '', 1761754199, 1761754199),
(49270, 'Ezekiel 36:25', 'Ezekiel', 36, 25, 'زه به په تاسو باندې پاکې اوبه وشیندم او تاسو به د ټولو بت‌پرستیو او ناپاکیو نه پاک کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel36_verse_25.mp3', '', 1761754199, 1761754199),
(49271, 'Ezekiel 36:26', 'Ezekiel', 36, 26, 'زه به تاسو ته نوی زړه او تازه روح درکړم. زه به ستاسو نه هغه د تیږې په شان کلک زړه لېرې کړم او یو نرم زړه به درکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel36_verse_26.mp3', '', 1761754199, 1761754199),
(49272, 'Ezekiel 36:27', 'Ezekiel', 36, 27, 'زه به په تاسو کې خپل روح واچوم او دا به د دې سبب شي چې تاسو زما په قوانینو او حکمونو باندې عمل وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel36_verse_27.mp3', '', 1761754199, 1761754199),
(49273, 'Ezekiel 36:28', 'Ezekiel', 36, 28, 'نو بیا به تاسو په هغه وطن کې واوسېږئ چې ستاسو نیکونو ته مې درکړی دی. تاسو به زما قوم یئ او زه به ستاسو خدای یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel36_verse_28.mp3', '', 1761754199, 1761754199),
(49274, 'Ezekiel 36:29', 'Ezekiel', 36, 29, 'زه به تاسو د ټولو ناپاکیو نه وژغورم. ستاسو غلې دانې به ډېرې زیاتې کړم، ترڅو تاسو نور د قحطیو سره مخامخ نه شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel36_verse_29.mp3', '', 1761754199, 1761754199),
(49275, 'Ezekiel 36:30', 'Ezekiel', 36, 30, 'زه به ستاسو د مېوو د ونو او د ځمکو حاصلات زیات کړم، ترڅو د قحطۍ له امله په نورو قومونو کې ونه شرمېږئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel36_verse_30.mp3', '', 1761754199, 1761754199),
(49276, 'Ezekiel 36:31', 'Ezekiel', 36, 31, 'نو تاسو ته به خپل بد‌چلند او غلط کارونه چې کړي مو دي، در په یاد شي او د خپلو ګناهونو او د کرکې وړ کارونو له امله به تاسو د خپلو ځانونو نه بېزاره او پښېمانه شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel36_verse_31.mp3', '', 1761754199, 1761754199),
(49277, 'Ezekiel 36:32', 'Ezekiel', 36, 32, 'ای اسراییلو، زه غواړم چې تاسو په دې پوه شئ چې زه دا ټول کارونه ستاسو په خاطر نه کوم. زه غواړم چې تاسو د خپلو کارونو له امله وشرمېږئ او چاته کتلی نه شئ. ما څښتن تعالی داسې ویلي دي.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel36_verse_32.mp3', '', 1761754199, 1761754199),
(49278, 'Ezekiel 36:33', 'Ezekiel', 36, 33, 'څښتن تعالی داسې وایي: ‹کله چې تاسو د ټولو ګناهونو نه پاک کړم، نو تاسو به پرېږدم چې بېرته په خپلو ښارونو کې واوسېږئ او کنډوالې بېرته ودانې کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel36_verse_33.mp3', '', 1761754199, 1761754199),
(49279, 'Ezekiel 36:34', 'Ezekiel', 36, 34, 'هرڅوک به چې ستاسو په ځمکو باندې تېرېده، نو هغوی به لیدل چې هغه ځمکې څنګه شاړې او خوشې پاتې وې، خو زه به پرېږدم هغه ځمکه چې مخکې شاړه وه، بېرته قلبه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel36_verse_34.mp3', '', 1761754199, 1761754199),
(49280, 'Ezekiel 36:35', 'Ezekiel', 36, 35, 'نو هغوی به ووایي چې دا ځمکه چې یو وخت شاړه وه، اوس ورڅخه د عدن باغ جوړ شوی دی او هغه ښارونه چې وران او په کنډوالو باندې بدل شوي وو، اوس قوي شوي او خلک په کې اوسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel36_verse_35.mp3', '', 1761754199, 1761754199),
(49281, 'Ezekiel 36:36', 'Ezekiel', 36, 36, 'نو ستاسو شاوخوا کوم قومونه چې ژوندي پاتې دي، هغوی به پوه شي چې ما څښتن هغه وران شوي ښارونه بېرته ودان کړل او هغه شاړې ځمکې مې بېرته راشنې کړلې. ما څښتن دا وعده کړې وه چې زه به دا کار وکړم.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel36_verse_36.mp3', '', 1761754199, 1761754199),
(49282, 'Ezekiel 36:37', 'Ezekiel', 36, 37, 'څښتن تعالی داسې وایي: ‹زه به یوځل بیا د اسراییلیانو دعاګانې قبولې کړم او د هغوی شمېر به د پسونو د رمې په شان زیات کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel36_verse_37.mp3', '', 1761754199, 1761754199),
(49283, 'Ezekiel 36:38', 'Ezekiel', 36, 38, 'لکه څنګه چې په یو وخت کې د اورشلیم ښار د اختر په ورځو کې د قربانۍ د پسونو نه ډک ؤ، نو همداسې به هغه ښارونه چې اوس وران او ویجاړ پراته دي، د خلکو نه ډک شي. بیا به هغوی پوه شي چې زه څښتن یم.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel36_verse_38.mp3', '', 1761754199, 1761754199),
(49284, 'Deuteronomy 1:1', 'Deuteronomy', 1, 1, 'په دې کتاب کې هغه خبرې دي چې موسی د اسراییلو خلکو ته په هغه وخت کې کړې وې کله چې هغوی د اردن د سیند ختیځې خواته په دښته کې وو. هغوی سوف ته نژدې د اردن په دره کې وو، یعنې د فاران د ښار چې په یو اړخ باندې ؤ او د توفل، لابان، حضیروت او د دي ذهب ښارونو ترمنځ چې په بل اړخ باندې وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy1_verse_1.mp3', '', 1761754199, 1761754199),
(49285, 'Deuteronomy 1:2', 'Deuteronomy', 1, 2, 'د ادوم د غرنۍ سیمې په لاره د حوریب یعنې د سینا د غره څخه تر قادش برنیع پورې د یوولسو ورځو لاره ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy1_verse_2.mp3', '', 1761754199, 1761754199),
(49286, 'Deuteronomy 1:3', 'Deuteronomy', 1, 3, 'د څلوېښتم کال د یوولسمې میاشتې په لومړۍ ورځ وروسته له دې چې د اسراییلو قوم د مصر څخه لاړ، موسی هغه ټول شیان چې څښتن د هغو په اړه ورته حکم کړی ؤ چې قوم ته یې ووایي، هغوی ته وویل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy1_verse_3.mp3', '', 1761754199, 1761754199),
(49287, 'Deuteronomy 1:4', 'Deuteronomy', 1, 4, 'دا کار وروسته له هغې وشو کله چې څښتن د اموریانو پاچا سیحون ته چې د حشبون ښار یې پایتخت ؤ او د باشان پاچا عوج ته چې د عشتاروت او ادرعي په ښارونو باندې یې حکومت کاوه، ماتې ورکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy1_verse_4.mp3', '', 1761754199, 1761754199),
(49288, 'Deuteronomy 1:5', 'Deuteronomy', 1, 5, 'موسی په داسې وخت کې د خدای قوانین بیان کړل چې قوم د اردن په ختیځ کې د موآب په سیمه کې ؤ. هغه وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy1_verse_5.mp3', '', 1761754199, 1761754199),
(49289, 'Deuteronomy 1:6', 'Deuteronomy', 1, 6, '«کله چې مونږ د سینا د غره سره وو، زمونږ څښتن خدای مونږ ته داسې وویل: ‹زیاته موده وشوه چې تاسو د دې غره په څنګ کې پاتې شوي یئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy1_verse_6.mp3', '', 1761754199, 1761754199),
(49290, 'Deuteronomy 1:7', 'Deuteronomy', 1, 7, 'خېمې راټولې کړئ او کډه وکړئ. د اموریانو غرنۍ سیمې او ټولو شاوخوا سیمو، د اردن درې، غرنۍ سیمې، د غرونو لوېدیځو لمنو، جنوبي سیمې او د مدیترانې د بحیرې غاړې ته لاړ شئ. د کنعان ځمکې ته او د لبنان د غرونو په لاره د فرات تر لوی سیند پورې لاړ شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy1_verse_7.mp3', '', 1761754199, 1761754199),
(49291, 'Deuteronomy 1:8', 'Deuteronomy', 1, 8, 'دا ټوله هغه ځمکه ده چې د هغې د ورکولو وعده مې ستاسو د نیکونو یعنې د ابراهیم، اسحاق او یعقوب او د هغوی د اولادې سره کړې وه. لاړ شئ او هغه ځمکه ونیسئ.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy1_verse_8.mp3', '', 1761754199, 1761754199),
(49292, 'Deuteronomy 1:9', 'Deuteronomy', 1, 9, 'موسی قوم ته وویل: «په داسې وخت کې چې مونږ لا د سینا د غره سره وو، ما تاسو ته وویل: ‹په تاسو باندې د مشرۍ کولو مسوولیت زما په وس کې نه دی. زه دا کار یوازې نه شم کولای.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy1_verse_9.mp3', '', 1761754199, 1761754199),
(49293, 'Deuteronomy 1:10', 'Deuteronomy', 1, 10, 'زمونږ څښتن خدای ستاسو شمېر دومره زیات کړی دی لکه د اسمان د ستورو په شان.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy1_verse_10.mp3', '', 1761754199, 1761754199),
(49294, 'Deuteronomy 1:11', 'Deuteronomy', 1, 11, 'زمونږ د نیکونو څښتن خدای دې تاسو زر چنده زیات کړي او تاسو ته دې د خپلې وعدې سره سم برکت درکړي!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy1_verse_11.mp3', '', 1761754199, 1761754199),
(49295, 'Deuteronomy 1:12', 'Deuteronomy', 1, 12, 'خو زه په یوازې ځان نه شم کولای دا دروند مسوولیت په غاړه واخلم چې ستاسو شخړې حل کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy1_verse_12.mp3', '', 1761754199, 1761754199),
(49296, 'Deuteronomy 1:13', 'Deuteronomy', 1, 13, 'د هرې قبیلې څخه پوه او تجربه لرونکي کسان غوره کړئ. زه به هغوی ستاسو مشران کړم.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy1_verse_13.mp3', '', 1761754199, 1761754199),
(49297, 'Deuteronomy 1:14', 'Deuteronomy', 1, 14, 'او تاسو وویل چې دا ښه کار دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy1_verse_14.mp3', '', 1761754199, 1761754199),
(49298, 'Deuteronomy 1:15', 'Deuteronomy', 1, 15, 'نو ما ستاسو د قبیلو څخه هغه پوه او تجربه لرونکي خلک واخیستل او په تاسو باندې مې د مشرانو په توګه وټاکل. ځینو د زرو کسانو مسوولیت په غاړه درلود، ځینو د سلو، ځینو د پنځوسو او ځینو د لسو کسانو مسوولیت په غاړه درلود. همدارنګه ما د ټولو قبیلو څخه نور مشران هم وټاکل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy1_verse_15.mp3', '', 1761754199, 1761754199),
(49299, 'Deuteronomy 1:16', 'Deuteronomy', 1, 16, 'په هغه وخت کې ما قاضیانو ته دا لارښوونې ورکړې: ‹هغو شخړو ته غوږ نیسئ چې ستاسو خلکو ترمنځ رامنځته کیږي. په عادلانه ډول د هرې شخړې قضاوت کوئ، که دا یوازې ستاسو په خلکو پورې اړه لري یا په هغو پردیو خلکو پورې چې ستاسو په منځ کې اوسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy1_verse_16.mp3', '', 1761754199, 1761754199),
(49300, 'Deuteronomy 1:17', 'Deuteronomy', 1, 17, 'په خپلو پرېکړو کې د هېچا طرفداري مه کوئ، په هرچا باندې یوشان قضاوت کوئ، دا مهمه نه ده چې هغه بې وزله وي یا قدرتمند. د هېچا څخه مه وېرېږئ، ځکه کومې پرېکړې چې تاسو یې کوئ هغه د خدای له خوا دي. که چېرې کومه دعوه ستاسو دپاره ګرانه وي، ماته یې راوړئ او زه به یې پرېکړه وکړم.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy1_verse_17.mp3', '', 1761754199, 1761754199),
(49301, 'Deuteronomy 1:18', 'Deuteronomy', 1, 18, 'په هماغه وخت کې ما تاسو ته د نورو ټولو کارونو په اړه چې تاسو یې باید سرته ورسوئ، لارښوونې وکړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy1_verse_18.mp3', '', 1761754199, 1761754199),
(49302, 'Deuteronomy 1:19', 'Deuteronomy', 1, 19, 'څه چې زمونږ څښتن خدای مونږ ته امر کړی ؤ هغه مو سرته ورسول. مونږ د سینا د غره څخه د پراخې او د وېرې څخه ډکې دښتې په لاره د اموریانو غرنۍ سیمې ته لاړو. کله چې مونږ قادش برنیع ته ورسېدلو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy1_verse_19.mp3', '', 1761754199, 1761754199),
(49303, 'Deuteronomy 1:22', 'Deuteronomy', 1, 22, 'خو تاسو ټول ماته راغلئ او ومو ویل: ‹مخکې له دې چې هغې خاورې ته ورشو، راځئ چې څو کسان ولېږو چې هغه وګوري، ترڅو مونږ ته سمه لاره وښایي چې ورباندې لاړ شو او راته ووایي چې هلته څه ډول ښارونه دي.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy1_verse_22.mp3', '', 1761754199, 1761754199),
(49304, 'Deuteronomy 1:23', 'Deuteronomy', 1, 23, 'دا کار ماته ښه ښکاره شو، نو ما دولس کسان یعنې د هرې قبیلې څخه مې یو یو کس غوره کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy1_verse_23.mp3', '', 1761754199, 1761754199),
(49305, 'Deuteronomy 1:24', 'Deuteronomy', 1, 24, 'هغوی غرنۍ سیمې ته د اشکول تر درې پورې لاړل او هغه ځای یې وکاته.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy1_verse_24.mp3', '', 1761754199, 1761754199),
(49306, 'Deuteronomy 1:25', 'Deuteronomy', 1, 25, 'هغوی مونږ ته د هغې خوا څخه لږه مېوه راوړله چې هلته یې پیدا کړې وه او خبر یې راوړ چې کومه ځمکه چې زمونږ څښتن خدای یې مونږ ته راکوي، هغه ډېره حاصلخېزه ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy1_verse_25.mp3', '', 1761754199, 1761754199),
(49307, 'Deuteronomy 1:26', 'Deuteronomy', 1, 26, 'خو تاسو ونه غوښتل چې هغې خاورې ته ورننوځئ او د خپل څښتن خدای د امر د منلو څخه مو سرغړونه وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy1_verse_26.mp3', '', 1761754199, 1761754199),
(49308, 'Deuteronomy 1:27', 'Deuteronomy', 1, 27, 'تاسو په خپلو خېمو کې پاتې شوئ، وغورېدئ او ومو ویل: ‹څښتن زمونږ څخه کرکه کوي. هغه مونږ د دې دپاره د مصر څخه راوویستلو چې اموریانو ته مو په لاس ورکړي، ترڅو مونږ ووژني.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy1_verse_27.mp3', '', 1761754199, 1761754199),
(49309, 'Deuteronomy 1:28', 'Deuteronomy', 1, 28, 'هلته ولې لاړ شو؟ مونږ وېرېږو. هغه کسان چې مونږ لېږلي وو مونږ ته وایي چې د هغه ځای خلک زمونږ څخه قوي او لوړ دي او هغوی په داسې ښارونو کې ژوند کوي چې دېوالونه یې اسمان ته رسیږي. حتی هغوی په هغه ځای کې عناقیان هم ولیدل چې ډېر لوړ قدونه یې درلودل!›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy1_verse_28.mp3', '', 1761754199, 1761754199),
(49310, 'Deuteronomy 1:29', 'Deuteronomy', 1, 29, 'خو ما وویل: ‹د هغو خلکو څخه مه وېرېږئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy1_verse_29.mp3', '', 1761754199, 1761754199);